// Clean HTML entities and markup
function cleanText(text) {
  if (!text) return "";
  return text
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

const seenUrls = new Set();
const seenTitles = new Set();
const normalizedItems = [];

for (const item of $input.all()) {
  try {
    const data = item.json || {};

    // Extract canonical title
    const rawTitle = data.title || data["title:"] || "";
    const title = cleanText(String(rawTitle));

    // Extract canonical URL (keep original link unaltered)
    const rawUrl = data.link || data.guid || data.origlink || "";
    const sourceUrl = (typeof rawUrl === "string") ? rawUrl.trim() : (data.guid?.["#text"] || "");

    // Must have a valid title and URL to be actionable
    if (!title || !sourceUrl) continue;

    // Deduplicate within the current execution batch
    const normalizedTitle = title.toLowerCase().replace(/[^a-z0-9]/g, "");
    if (seenUrls.has(sourceUrl) || seenTitles.has(normalizedTitle)) {
      continue;
    }
    seenUrls.add(sourceUrl);
    seenTitles.add(normalizedTitle);

    // Extract and clean description or summary
    const rawDesc = data.contentSnippet || data.description || data.summary || data.content || "";
    const description = cleanText(String(rawDesc));

    // Parse and normalize publication date (ISO 8601)
    let pubDateIso = new Date().toISOString();
    const rawDate = data.pubDate || data.isoDate || data.date;
    if (rawDate) {
      try {
        const parsed = new Date(rawDate);
        if (!isNaN(parsed.getTime())) {
          pubDateIso = parsed.toISOString();
        }
      } catch (e) {}
    }

    // Source metadata from upstream tagger
    const sourceName = data._meta_source || "RSS Source";
    let category = data._meta_category || "SCIENCE";

    // Secondary Category Refinement for VOIDORA Pillars (Space, Science, History, Mysteries)
    const fullText = (title + " " + description).toLowerCase();
    if (fullText.includes("mystery") || fullText.includes("unexplained") || fullText.includes("bizarre") || fullText.includes("enigma") || fullText.includes("anomal")) {
      category = "MYSTERIES";
    } else if (fullText.includes("ancient") || fullText.includes("archaeolog") || fullText.includes("century") || fullText.includes("civilization") || fullText.includes("histor")) {
      category = "HISTORY";
    } else if (fullText.includes("space") || fullText.includes("nasa") || fullText.includes("galaxy") || fullText.includes("planet") || fullText.includes("asteroid") || fullText.includes("telescope") || fullText.includes("cosm")) {
      category = "SPACE";
    }

    normalizedItems.push({
      json: {
        title,
        source: sourceName,
        source_url: sourceUrl,
        original_article_url: sourceUrl,
        publication_date: pubDateIso,
        description,
        category,
        discovery_timestamp: new Date().toISOString()
      }
    });
  } catch (err) {
    // Graceful error capture per item to prevent batch failure
    continue;
  }
}

return normalizedItems;

const items = $input.all();
const scoredItems = [];

// Curated heuristic keywords for VOIDORA documentary pillars
const HIGH_IMPACT_HOOKS = [
  "mystery", "unexplained", "secret", "ancient", "origin", "discovery",
  "bizarre", "first time", "unprecedented", "hidden", "black hole",
  "deep space", "alien", "extinction", "cataclysm", "lost civilization",
  "forbidden", "shocking", "quantum", "rewrites history", "paradox",
  "dark matter", "voyager", "james webb", "exoplanet", "tomb", "ruins"
];

const MODERATE_ENGAGEMENT_HOOKS = [
  "reveals", "breakthrough", "new evidence", "astronomers", "scientists find",
  "anomaly", "signal", "danger", "collision", "investigation", "uncovered",
  "rare", "unknown", "deep sea", "fossil", "prehistoric", "expedition"
];

const LOW_VALUE_ADMIN_TERMS = [
  "quarterly report", "budget", "meeting", "conference", "appointment",
  "administrator", "statement on", "press release", "contract awarded",
  "briefing", "schedule update", "symposium", "advisory", "grant"
];

for (const item of items) {
  try {
    const d = item.json || {};
    const title = d.title || "";
    const description = d.description || "";
    const combinedText = (title + " " + description).toLowerCase();

    let score = 50; // Neutral baseline
    const scoreBreakdown = ["Base neutral score: +50"];

    // 1. Keyword impact checks
    let highImpactHits = 0;
    for (const kw of HIGH_IMPACT_HOOKS) {
      if (combinedText.includes(kw)) {
        highImpactHits++;
      }
    }
    if (highImpactHits > 0) {
      const boost = Math.min(25, highImpactHits * 8);
      score += boost;
      scoreBreakdown.push(`High curiosity hook keywords (${highImpactHits} match): +${boost}`);
    }

    let modImpactHits = 0;
    for (const kw of MODERATE_ENGAGEMENT_HOOKS) {
      if (combinedText.includes(kw)) {
        modImpactHits++;
      }
    }
    if (modImpactHits > 0) {
      const boost = Math.min(15, modImpactHits * 5);
      score += boost;
      scoreBreakdown.push(`Scientific discovery terms (${modImpactHits} match): +${boost}`);
    }

    // Administrative penalty
    let adminHits = 0;
    for (const term of LOW_VALUE_ADMIN_TERMS) {
      if (combinedText.includes(term)) {
        adminHits++;
      }
    }
    if (adminHits > 0) {
      const penalty = adminHits * 20;
      score -= penalty;
      scoreBreakdown.push(`Administrative/routine notice terms (${adminHits} match): -${penalty}`);
    }

    // 2. Substantive content length heuristic
    if (description.length >= 200) {
      score += 10;
      scoreBreakdown.push("Rich editorial summary (>=200 chars): +10");
    } else if (description.length < 50) {
      score -= 10;
      scoreBreakdown.push("Very brief summary (<50 chars): -10");
    }

    // 3. Recency heuristic (bonus for fresh news under 24 hours)
    if (d.publication_date) {
      try {
        const pubTime = new Date(d.publication_date).getTime();
        if (!isNaN(pubTime)) {
          const hoursOld = (Date.now() - pubTime) / (1000 * 60 * 60);
          if (hoursOld <= 24 && hoursOld >= 0) {
            score += 10;
            scoreBreakdown.push("Recent publication (<24h): +10");
          } else if (hoursOld <= 72 && hoursOld >= 0) {
            score += 5;
            scoreBreakdown.push("Recent publication (<72h): +5");
          }
        }
      } catch (e) {}
    }

    // Clamp score strictly between 0 and 100
    const finalScore = Math.max(0, Math.min(100, Math.round(score)));

    // Determine formats
    const isLongCandidate = finalScore >= 65 && description.length >= 100;
    const isShortsCandidate = finalScore >= 50 && (highImpactHits >= 1 || modImpactHits >= 1);

    // Status: candidate_for_research if score >= 70, else discovered
    const status = finalScore >= 70 ? "candidate_for_research" : "discovered";

    scoredItems.push({
      json: {
        ...d,
        editorial_priority_score: finalScore,
        score_type: "heuristic_editorial_score",
        score_notes: "Heuristic documentary potential score based on narrative tension and discovery keywords; does not reflect actual YouTube audience analytics.",
        score_breakdown: scoreBreakdown,
        is_long_documentary_candidate: isLongCandidate,
        is_shorts_candidate: isShortsCandidate,
        recommended_format: isLongCandidate ? "8-12 min Long Documentary" : (isShortsCandidate ? "60s Vertical Short" : "Background Archive"),
        status: status
      }
    });
  } catch (err) {
    continue;
  }
}

// Sort by highest priority score descending
scoredItems.sort((a, b) => b.json.editorial_priority_score - a.json.editorial_priority_score);

return scoredItems;

// Research candidates summary output
const candidates = $input.all();
return candidates.map(item => ({
  json: {
    ...item.json,
    pipeline_stage: "ready_for_research",
    editorial_note: `Candidate selected for VOIDORA queue with score ${item.json.editorial_priority_score}/100.`
  }
}));

// Discovered archive output
const discovered = $input.all();
return discovered.map(item => ({
  json: {
    ...item.json,
    pipeline_stage: "archived_discovery",
    editorial_note: "Discovered topic stored in background archive (below research threshold)."
  }
}));
